const isPinC = (c) => Math.abs(c[0] - 0.53) < 0.03 && c[1] < 0.05 && c[2] < 0.05;
const isBody = (c) => Math.abs(c[0] - 0.63) < 0.03 && c[1] < 0.05 && c[2] < 0.05;
const colOf = (c) => c.map((v) => v.toFixed(2)).join(',');

