  }
  if (cur) wires.push(cur);
}
const pts = []; const TOL = 0.9;
const addPt = (arr, p) => { for (let i = 0; i < arr.length; i++) if (Math.hypot(arr[i][0] - p[0], arr[i][1] - p[1]) < TOL) return i; arr.push([p[0], p[1]]); return arr.length - 1; };
