  let d = `M ${f(w[0][0])} ${f(w[0][1])} `;
  for (let i = 1; i < w.length; i++) d += `L ${f(w[i][0])} ${f(w[i][1])} `;
  out.push(`<path d="${d}" fill="none" stroke="${c}" stroke-width="${lab ? 2.6 : 1.5}" stroke-linecap="round"/>`);
}
